pub fn lookup(name: &str) -> Option<(&'static str, &'static [Signature])> {
    Some(match name {
        "add" => ("add", ADD),
        "subtract" => ("subtract", SUBTRACT),
        "multiply" => ("multiply", MULTIPLY),
        "divide" => ("divide", DIVIDE),
        "pow" => ("pow", POW),
        "mod" => ("mod", MOD),
        "unaryMinus" => ("unaryMinus", UNARY_MINUS),
        "unaryPlus" => ("unaryPlus", UNARY_PLUS),
        "factorial" => ("factorial", FACTORIAL),
        "ctranspose" => ("ctranspose", CTRANSPOSE),
        "bitAnd" => ("bitAnd", BIT_AND),
        "bitOr" => ("bitOr", BIT_OR),
        "bitXor" => ("bitXor", BIT_XOR),
        "bitNot" => ("bitNot", BIT_NOT),
        "leftShift" => ("leftShift", LEFT_SHIFT),
        "rightArithShift" => ("rightArithShift", RIGHT_ARITH_SHIFT),
        "rightLogShift" => ("rightLogShift", RIGHT_LOG_SHIFT),
        "and" => ("and", AND),
        "or" => ("or", OR),
        "xor" => ("xor", XOR),
        "not" => ("not", NOT),
        "equal" => ("equal", EQUAL),
        "unequal" => ("unequal", UNEQUAL),
        "smaller" => ("smaller", SMALLER),
        "larger" => ("larger", LARGER),
        "smallerEq" => ("smallerEq", SMALLER_EQ),
        "largerEq" => ("largerEq", LARGER_EQ),
        "dotMultiply" => ("dotMultiply", DOT_MULTIPLY),
        "dotDivide" => ("dotDivide", DOT_DIVIDE),
        "dotPow" => ("dotPow", DOT_POW),
        "abs" => ("abs", ABS),
        "sqrt" => ("sqrt", SQRT),
        "cbrt" => ("cbrt", CBRT),
        "exp" => ("exp", EXP),
        "log" => ("log", LOG),
        "log10" => ("log10", LOG10),
        "log2" => ("log2", LOG2),
        "round" => ("round", ROUND),
        "floor" => ("floor", FLOOR),
        "ceil" => ("ceil", CEIL),
        "fix" => ("fix", FIX),
        "sign" => ("sign", SIGN),
        "min" => ("min", MIN),
        "max" => ("max", MAX),
        "sin" => ("sin", SIN),
        "cos" => ("cos", COS),
        "tan" => ("tan", TAN),
        "asin" => ("asin", ASIN),
        "acos" => ("acos", ACOS),
        "atan" => ("atan", ATAN),
        "atan2" => ("atan2", ATAN2),
        "number" => ("number", NUMBER),
        "square" => ("square", SQUARE),
        "cube" => ("cube", CUBE),
        "gamma" => ("gamma", GAMMA),
        "addScalar" => ("addScalar", ADD_SCALAR),
        "multiplyScalar" => ("multiplyScalar", MULTIPLY_SCALAR),
        "equalScalar" => ("equalScalar", EQUAL_SCALAR),
        "conj" => ("conj", CONJ),
        _ => return None,
    })
}
